#!/usr/bin/env python3
"""Bridge QEMU serial (unix socket) <-> TCP 6665, logging all output.

On each new TCP client a newline is sent to the guest so the getty
re-prints its login prompt immediately.
"""
import os
import select
import socket
import sys
import time

SOCK = "/tmp/qemu-serial.sock"
PORT = 6665
LOG = "/tmp/serial.log"


def connect_guest():
    while True:
        try:
            s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            s.connect(SOCK)
            return s
        except OSError:
            time.sleep(0.5)


def main():
    guest = connect_guest()
    log = open(LOG, "ab", buffering=0)

    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(("127.0.0.1", PORT))
    srv.listen(5)

    client = None
    while True:
        rl = [guest, srv] + ([client] if client else [])
        r, _, _ = select.select(rl, [], [], 1.0)
        if srv in r:
            c, _ = srv.accept()
            if client:
                try:
                    client.close()
                except OSError:
                    pass
            client = c
            try:
                guest.send(b"\r")
            except OSError:
                pass
        if guest in r:
            try:
                data = guest.recv(65536)
            except OSError:
                data = b""
            if not data:
                guest.close()
                guest = connect_guest()
                continue
            log.write(data)
            if client:
                try:
                    client.sendall(data)
                except OSError:
                    client.close()
                    client = None
        if client and client in r:
            try:
                data = client.recv(65536)
            except OSError:
                data = b""
            if not data:
                client.close()
                client = None
            else:
                try:
                    guest.sendall(data)
                except OSError:
                    pass


if __name__ == "__main__":
    main()

